package com.examineplus;

/**
 * A single drop source for an item, parsed from the OSRS Wiki 'dropsline' bucket.
 */
class DropSource
{
	final String source;      // monster/source name (base name, variant stripped)
	final String variant;     // variant qualifier (e.g. "Zaros") or "" if none
	final String level;       // combat level(s), comma-separated as provided, or ""
	final String quantity;    // display quantity string, e.g. "1" or "1-100 (noted)"
	final String rarity;      // display rarity string, e.g. "1/128", "Always", "Common"
	final double probability; // parsed drop chance for sorting; NaN if unknown

	DropSource(String source, String variant, String level, String quantity, String rarity, double probability)
	{
		this.source = source;
		this.variant = variant;
		this.level = level;
		this.quantity = quantity;
		this.rarity = rarity;
		this.probability = probability;
	}

	/**
	 * Parse a wiki rarity string into an approximate probability for sorting.
	 * Handles "a/b" fractions and "Always"; returns NaN for non-numeric words (Common/Rare/etc).
	 */
	static double parseProbability(String rarity)
	{
		if (rarity == null || rarity.isEmpty())
		{
			return Double.NaN;
		}
		if (rarity.equalsIgnoreCase("Always"))
		{
			return 1.0;
		}
		final int slash = rarity.indexOf('/');
		if (slash > 0)
		{
			try
			{
				final double num = Double.parseDouble(rarity.substring(0, slash).trim().replace(",", ""));
				final double den = Double.parseDouble(rarity.substring(slash + 1).trim().replace(",", ""));
				if (den != 0)
				{
					return num / den;
				}
			}
			catch (NumberFormatException ignored)
			{
				// fall through
			}
		}
		return Double.NaN;
	}
}

package com.examineplus;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

/**
 * Fetches item drop sources + rarity from the OSRS Wiki Bucket API (action=bucket).
 * All network calls are async (OkHttp enqueue); results are cached per item name for the session.
 */
@Slf4j
@Singleton
class DropSourceService
{
	private static final HttpUrl API = HttpUrl.get("https://oldschool.runescape.wiki/api.php");
	// The wiki asks scrapers to identify themselves with a descriptive User-Agent.
	private static final String USER_AGENT = "examine-plus (RuneLite plugin; https://github.com/nikolajs/examine-plus)";

	private final OkHttpClient httpClient;
	private final Gson gson;

	private final Map<String, List<DropSource>> cache = new ConcurrentHashMap<>();

	@FunctionalInterface
	interface Callback2
	{
		void onResult(String itemName, List<DropSource> sources);
	}

	@Inject
	DropSourceService(OkHttpClient httpClient, Gson gson)
	{
		this.httpClient = httpClient;
		this.gson = gson;
	}

	/**
	 * Look up drop sources for an item by name. Fires the callback (on an OkHttp thread) with the
	 * result, or an empty list on error / no sources. Cached results fire the callback synchronously.
	 */
	void lookup(String itemName, Callback2 callback)
	{
		final List<DropSource> cached = cache.get(itemName);
		if (cached != null)
		{
			callback.onResult(itemName, cached);
			return;
		}

		// Bucket query is a Lua expression; use double quotes around the value so item names
		// containing apostrophes (e.g. "Verac's helm") don't break the string.
		final String query = "bucket('dropsline').select('item_name','drop_json')"
			+ ".where('item_name',\"" + itemName.replace("\"", "") + "\").limit(200).run()";

		final HttpUrl url = API.newBuilder()
			.addQueryParameter("action", "bucket")
			.addQueryParameter("format", "json")
			.addQueryParameter("query", query)
			.build();

		final Request request = new Request.Builder()
			.url(url)
			.header("User-Agent", USER_AGENT)
			.build();

		httpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("Drop source lookup failed for {}", itemName, e);
				callback.onResult(itemName, Collections.emptyList());
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (ResponseBody body = response.body())
				{
					if (!response.isSuccessful() || body == null)
					{
						callback.onResult(itemName, Collections.emptyList());
						return;
					}

					final List<DropSource> sources = parse(body.string());
					cache.put(itemName, sources);
					callback.onResult(itemName, sources);
				}
				catch (Exception e)
				{
					log.debug("Failed to parse drop sources for {}", itemName, e);
					callback.onResult(itemName, Collections.emptyList());
				}
			}
		});
	}

	private List<DropSource> parse(String responseBody)
	{
		final JsonObject root = gson.fromJson(responseBody, JsonObject.class);
		if (root == null || root.has("error") || !root.has("bucket"))
		{
			return Collections.emptyList();
		}

		final JsonArray rows = root.getAsJsonArray("bucket");
		final List<DropSource> sources = new ArrayList<>(rows.size());
		for (JsonElement rowEl : rows)
		{
			if (!rowEl.isJsonObject())
			{
				continue;
			}
			final JsonElement dropJsonEl = rowEl.getAsJsonObject().get("drop_json");
			if (dropJsonEl == null || dropJsonEl.isJsonNull())
			{
				continue;
			}

			// drop_json is itself a JSON string that must be parsed a second time.
			final JsonObject d = gson.fromJson(dropJsonEl.getAsString(), JsonObject.class);
			if (d == null)
			{
				continue;
			}

			final String from = str(d, "Dropped from");
			if (from.isEmpty())
			{
				continue;
			}

			// The dropsline bucket also records non-combat acquisition (reward/thieving/construction
			// sources like "Pile of Buckets" or "Tool store 2"). Only real monster kills belong on the
			// Drops tab — anything else has no monster wiki page and just adds noise.
			final String dropType = str(d, "Drop type");
			if (!dropType.isEmpty() && !dropType.equalsIgnoreCase("combat"))
			{
				continue;
			}

			String base = from;
			String variant = "";
			final int hash = from.indexOf('#');
			if (hash >= 0)
			{
				base = from.substring(0, hash);
				variant = from.substring(hash + 1);
			}

			final String rarity = str(d, "Rarity");
			sources.add(new DropSource(
				base,
				variant,
				str(d, "Drop level"),
				str(d, "Drop Quantity"),
				rarity,
				DropSource.parseProbability(rarity)));
		}

		// Most-common first; unknown/non-numeric rarities sorted last.
		sources.sort(Comparator.comparingDouble((DropSource s) ->
			Double.isNaN(s.probability) ? -1.0 : s.probability).reversed());

		return Collections.unmodifiableList(sources);
	}

	private static String str(JsonObject o, String key)
	{
		final JsonElement e = o.get(key);
		return (e == null || e.isJsonNull()) ? "" : e.getAsString();
	}
}

package com.examineplus;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("examineplus")
public interface ExaminePlusConfig extends Config
{
	@ConfigItem(
		keyName = "openPanelOnExamine",
		name = "Open panel on examine",
		description = "Automatically open the Examine Plus side panel when you examine an item"
	)
	default boolean openPanelOnExamine()
	{
		return false;
	}

	@ConfigItem(
		keyName = "showChatVerdict",
		name = "Examine chat message",
		description = "Append a one-line verdict to the examine chat message when an item is needed for a quest you haven't completed"
	)
	default boolean showChatVerdict()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showItemSources",
		name = "Show item sources & info",
		description = "Look up extra item info from the OSRS Wiki when examined: what it's used to make, how to make it, a one-line description, drop sources, spawn locations and shops",
		warning = "This feature submits your IP address to a 3rd-party server not controlled or verified by RuneLite developers"
	)
	default boolean showItemSources()
	{
		return false;
	}
}

package com.examineplus;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.awt.Rectangle;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.Scrollable;
import javax.swing.SwingConstants;
import net.runelite.api.QuestState;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.util.AsyncBufferedImage;
import net.runelite.client.util.QuantityFormatter;

/**
 * "A+B" examine panel: item-card header (icon · name · GE/alch value), a bold verdict headline,
 * then colour-coded quest and source cards that appear only when they have content. The sources
 * card is a tabbed Spawns · Shops · Drops control (design "B"): spawn rows pin the world map, drop
 * rows open the monster's wiki page. Spacing and colours mirror the pixel-faithful HTML mock (8px
 * section gaps; RuneLite ColorScheme). Everything is laid out by {@link #render()} on the Swing EDT.
 */
class ExaminePlusPanel extends PluginPanel
{
	private static final int GAP = 8;
	private static final int NOTABLE_GE = 50_000;
	private static final double RARE_DROP = 1.0 / 500.0;
	// A long list section (Uses / How to make / a Sources tab) grows to at most this many pixels of
	// rows, then scrolls internally; shorter sections size to their content and never scroll.
	private static final int MAX_SECTION_H = 180;

	private static final Color KEEP = new Color(0xEF, 0x4B, 0x4B);
	private static final Color NOTABLE = new Color(0xF0, 0xCF, 0x7B);
	private static final Color JUNK = new Color(0x8A, 0x8A, 0x8A);
	private static final Color DONE = new Color(0x6A, 0x6A, 0x6A);
	private static final Color FAINT = new Color(0x6A, 0x6A, 0x6A);
	private static final Color SPAWN = new Color(0x8F, 0xD0, 0xFF);
	private static final Color MEMBERS = new Color(0x7A, 0x9A, 0x5A);

	private static final Color R_ALWAYS = ColorScheme.PROGRESS_COMPLETE_COLOR;
	private static final Color R_COMMON = new Color(0x6E, 0xE1, 0x6E);
	private static final Color R_UNCOMMON = ColorScheme.LIGHT_GRAY_COLOR;
	private static final Color R_RARE = new Color(0xF0, 0xCF, 0x7B);
	private static final Color R_VERYRARE = new Color(0xEF, 0x4B, 0x4B);

	enum SourceTab
	{
		SPAWNS("Spawns"), SHOPS("Shops"), DROPS("Drops");

		final String label;

		SourceTab(String label)
		{
			this.label = label;
		}
	}

	/** Callbacks into the plugin for interactions the panel can't perform itself. */
	interface SourceActions
	{
		/**
		 * Pin the given spawn tiles on the world map and navigate to them.
		 *
		 * @param toggle if true, clicking the same selection again clears the pins (used by "Show all");
		 *               if false, always (re)shows the selection (used by a single region row)
		 */
		void showOnMap(int itemId, List<WorldPoint> points, String label, boolean toggle);

		void openMonsterWiki(String monsterName);

		/** Open an item's OSRS Wiki page (used by recipe product and ingredient rows). */
		void openItemWiki(String itemName);
	}

	private final JPanel content = new JPanel();

	// persistent header/verdict widgets (contents updated per item)
	private final JPanel header = new JPanel(new BorderLayout(9, 0));
	private final JLabel iconLabel = new JLabel();
	private final JLabel nameLabel = new JLabel();
	private final JLabel valueLabel = new JLabel();
	private final JLabel verdictLabel = new JLabel();
	private final JLabel reasonLabel = new JLabel();

	private SourceActions actions;

	// current item state
	private int currentItemId = -1;
	private String currentItemName = "";
	private List<QuestFlag> quests = new ArrayList<>();
	private boolean sourcesRequested = false;
	private List<DropSource> dropSources = null;   // null = loading, empty = none found
	private List<SpawnArea> spawnAreas = null;     // null = loading, empty = none found (surface, by place)
	private WorldPoint playerLocation = null;      // player's tile when spawns were fetched (for distance)
	private List<StoreSource> storeSources = null; // null = loading, empty = none found
	private String summary = null;                 // null = loading, "" = none; one-line wiki description
	private List<ItemRecipe> uses = null;          // null = loading, empty = none; products this item makes
	private List<ItemRecipe> recipe = null;        // null = loading, empty = none; this item's own recipe(s)
	private SourceTab activeTab = SourceTab.SPAWNS;
	private int gePrice = 0;

	ExaminePlusPanel()
	{
		setLayout(new BorderLayout());
		setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));

		content.setLayout(new BoxLayout(content, BoxLayout.Y_AXIS));
		content.setOpaque(false);

		iconLabel.setPreferredSize(new Dimension(34, 32));
		iconLabel.setHorizontalAlignment(SwingConstants.CENTER);

		final JPanel titles = new JPanel();
		titles.setLayout(new BoxLayout(titles, BoxLayout.Y_AXIS));
		titles.setOpaque(false);
		nameLabel.setFont(FontManager.getRunescapeBoldFont());
		nameLabel.setForeground(Color.WHITE);
		nameLabel.setAlignmentX(LEFT_ALIGNMENT);
		valueLabel.setFont(FontManager.getRunescapeSmallFont());
		valueLabel.setAlignmentX(LEFT_ALIGNMENT);
		titles.add(nameLabel);
		titles.add(valueLabel);

		header.setOpaque(false);
		header.setAlignmentX(LEFT_ALIGNMENT);
		header.setMaximumSize(new Dimension(Integer.MAX_VALUE, 40));
		header.add(iconLabel, BorderLayout.WEST);
		header.add(titles, BorderLayout.CENTER);

		verdictLabel.setFont(FontManager.getRunescapeBoldFont());
		verdictLabel.setAlignmentX(LEFT_ALIGNMENT);
		reasonLabel.setFont(FontManager.getRunescapeSmallFont());
		reasonLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		reasonLabel.setAlignmentX(LEFT_ALIGNMENT);
		reasonLabel.setBorder(BorderFactory.createEmptyBorder(2, 13, 0, 0));

		add(content, BorderLayout.NORTH);
		showEmpty();
	}

	void setActions(SourceActions actions)
	{
		this.actions = actions;
	}

	void showEmpty()
	{
		currentItemId = -1;
		currentItemName = "";
		quests = new ArrayList<>();
		sourcesRequested = false;
		dropSources = null;
		spawnAreas = null;
		storeSources = null;
		summary = null;
		uses = null;
		recipe = null;
		iconLabel.setIcon(null);
		nameLabel.setText("Examine Plus");
		valueLabel.setText("");

		content.removeAll();
		content.add(header);
		content.add(Box.createVerticalStrut(GAP));
		content.add(muted("Examine an item in-game to see quest usage, value and where to get it."));
		refresh();
	}

	void displayItem(int itemId, String itemName, AsyncBufferedImage icon,
		int gePrice, int alchPrice, List<QuestFlag> quests, boolean sourcesRequested)
	{
		this.currentItemId = itemId;
		this.currentItemName = itemName;
		this.quests = quests;
		this.sourcesRequested = sourcesRequested;
		this.dropSources = null;
		this.spawnAreas = null;
		this.storeSources = null;
		this.summary = null;
		this.uses = null;
		this.recipe = null;
		this.activeTab = SourceTab.SPAWNS;
		this.gePrice = gePrice;

		nameLabel.setText(itemName);
		iconLabel.setIcon(null);
		if (icon != null)
		{
			icon.addTo(iconLabel);
		}
		setValueLine(gePrice, alchPrice);

		render();
	}

	void setDrops(int itemId, List<DropSource> sources)
	{
		if (itemId != currentItemId)
		{
			return;
		}
		this.dropSources = sources;
		render();
	}

	void setSpawns(int itemId, List<SpawnArea> areas, WorldPoint playerLocation)
	{
		if (itemId != currentItemId)
		{
			return;
		}
		this.spawnAreas = areas;
		this.playerLocation = playerLocation;
		render();
	}

	void setStores(int itemId, List<StoreSource> sources)
	{
		if (itemId != currentItemId)
		{
			return;
		}
		this.storeSources = sources;
		render();
	}

	void setSummary(int itemId, String text)
	{
		if (itemId != currentItemId)
		{
			return;
		}
		this.summary = text;
		render();
	}

	void setUses(int itemId, List<ItemRecipe> recipes)
	{
		if (itemId != currentItemId)
		{
			return;
		}
		this.uses = recipes;
		render();
	}

	void setRecipe(int itemId, List<ItemRecipe> recipes)
	{
		if (itemId != currentItemId)
		{
			return;
		}
		this.recipe = recipes;
		render();
	}

	private void render()
	{
		final List<QuestFlag> needed = new ArrayList<>();
		final List<QuestFlag> done = new ArrayList<>();
		for (QuestFlag q : quests)
		{
			(q.completed() ? done : needed).add(q);
		}

		applyVerdict(needed);

		content.removeAll();
		content.add(header);

		if (summary != null && !summary.isEmpty())
		{
			content.add(Box.createVerticalStrut(GAP));
			content.add(wrapped(summary));
		}

		if (!verdictLabel.getText().isEmpty())
		{
			content.add(Box.createVerticalStrut(GAP));
			content.add(verdictLabel);
			if (!reasonLabel.getText().isEmpty())
			{
				content.add(reasonLabel);
			}
		}

		if (!quests.isEmpty())
		{
			content.add(Box.createVerticalStrut(GAP));
			content.add(buildQuestCard(needed, done));
		}

		if (uses != null && !uses.isEmpty())
		{
			content.add(Box.createVerticalStrut(GAP));
			content.add(buildUsesCard());
		}

		if (recipe != null && !recipe.isEmpty())
		{
			content.add(Box.createVerticalStrut(GAP));
			content.add(buildRecipeCard());
		}

		if (sourcesRequested)
		{
			content.add(Box.createVerticalStrut(GAP));
			content.add(buildSourcesCard());
		}

		refresh();
	}

	private void applyVerdict(List<QuestFlag> needed)
	{
		if (!needed.isEmpty())
		{
			final String reason = needed.size() == 1
				? needed.get(0).questName + " — " + needed.get(0).statusText()
				: "Needed for " + needed.size() + " quests you haven't done";
			setVerdict("Keep · quest item", KEEP, reason);
			return;
		}
		if (gePrice >= NOTABLE_GE)
		{
			setVerdict("Worth keeping", NOTABLE, "Worth " + QuantityFormatter.formatNumber(gePrice) + " gp");
			return;
		}
		final DropSource rarest = rarestSource();
		if (rarest != null)
		{
			setVerdict("Worth keeping", NOTABLE, "Rare drop · " + rarest.rarity + " from " + rarest.source);
			return;
		}
		// No positive reason to keep it: show no verdict at all rather than a "safe to drop" line.
		setVerdict("", JUNK, "");
	}

	private DropSource rarestSource()
	{
		if (dropSources == null)
		{
			return null;
		}
		DropSource rarest = null;
		for (DropSource s : dropSources)
		{
			if (!Double.isNaN(s.probability) && s.probability > 0 && s.probability <= RARE_DROP
				&& (rarest == null || s.probability < rarest.probability))
			{
				rarest = s;
			}
		}
		return rarest;
	}

	// --- section builders ---

	private JPanel buildQuestCard(List<QuestFlag> needed, List<QuestFlag> done)
	{
		final JPanel card = card();
		card.add(sectionLabel("Quests", null));
		for (QuestFlag q : needed)
		{
			card.add(questRow(q.questName, false));
		}
		if (!done.isEmpty())
		{
			final JPanel body = plain();
			for (QuestFlag q : done)
			{
				body.add(questRow(q.questName, true));
			}
			body.setVisible(false);
			card.add(expander(done.size() + " completed", body));
			card.add(body);
		}
		return card;
	}

	/** "Uses" card: the products the examined item helps make; each row opens the product's wiki page. */
	private JPanel buildUsesCard()
	{
		final JPanel card = card();
		card.add(sectionLabel("Uses", String.valueOf(uses.size())));
		final ScrollList list = new ScrollList();
		for (ItemRecipe r : uses)
		{
			final String qty = (r.outputQuantity == null || r.outputQuantity.isEmpty()
				|| "1".equals(r.outputQuantity)) ? "" : "×" + r.outputQuantity;
			list.add(itemLinkRow(r.output, qty, FAINT));
		}
		card.add(scrollCapped(list));
		return card;
	}

	/** "How to make" card: the item's own recipe(s) — skill/level requirement, materials, and a note. */
	private JPanel buildRecipeCard()
	{
		final JPanel card = card();
		card.add(sectionLabel("How to make", null));
		final ScrollList list = new ScrollList();
		boolean first = true;
		for (ItemRecipe r : recipe)
		{
			if (!first)
			{
				list.add(Box.createVerticalStrut(5));
			}
			first = false;

			for (ItemRecipe.SkillReq s : r.skills)
			{
				list.add(requirementRow(s));
			}
			for (ItemRecipe.Ingredient m : r.materials)
			{
				final String qty = (m.quantity == null || m.quantity.isEmpty()) ? "" : m.quantity + " × ";
				list.add(itemLinkRow(qty + m.name, "", FAINT, m.name));
			}
			final String note = recipeNote(r);
			if (!note.isEmpty())
			{
				list.add(muted(note));
			}
		}
		card.add(scrollCapped(list));
		return card;
	}

	/** A "Chisel · Anvil · members" style footnote from a recipe's tool/facility/members fields. */
	private static String recipeNote(ItemRecipe r)
	{
		final List<String> parts = new ArrayList<>();
		if (r.tools != null && !r.tools.isEmpty())
		{
			parts.add(r.tools);
		}
		if (r.facility != null && !r.facility.isEmpty())
		{
			parts.add(r.facility);
		}
		if (r.members)
		{
			parts.add("members");
		}
		return String.join(" · ", parts);
	}

	/**
	 * Tabbed sources card. A tab is shown while its data is still loading (null) or once it has
	 * content; tabs that load empty are dropped. With a single tab the tab bar collapses to a plain
	 * section header.
	 */
	private JPanel buildSourcesCard()
	{
		final JPanel card = card();

		final List<SourceTab> tabs = new ArrayList<>();
		if (spawnAreas == null || !spawnAreas.isEmpty())
		{
			tabs.add(SourceTab.SPAWNS);
		}
		if (storeSources == null || !storeSources.isEmpty())
		{
			tabs.add(SourceTab.SHOPS);
		}
		if (dropSources == null || !dropSources.isEmpty())
		{
			tabs.add(SourceTab.DROPS);
		}

		if (tabs.isEmpty())
		{
			card.add(sectionLabel("Sources", null));
			card.add(muted("No sources found."));
			return card;
		}

		if (!tabs.contains(activeTab))
		{
			activeTab = tabs.get(0);
		}

		if (tabs.size() == 1)
		{
			final SourceTab only = tabs.get(0);
			card.add(sectionLabel(only.label, tabCount(only)));
		}
		else
		{
			card.add(buildTabBar(tabs));
			card.add(Box.createVerticalStrut(5));
		}

		card.add(scrollCapped(buildPane(activeTab)));
		return card;
	}

	private JPanel buildTabBar(List<SourceTab> tabs)
	{
		final JPanel bar = new JPanel(new GridLayout(1, tabs.size(), 2, 0));
		bar.setOpaque(false);
		bar.setAlignmentX(LEFT_ALIGNMENT);
		bar.setMaximumSize(new Dimension(Integer.MAX_VALUE, 20));
		bar.setBorder(BorderFactory.createEmptyBorder(0, 0, 4, 0));

		for (SourceTab tab : tabs)
		{
			final boolean active = tab == activeTab;
			final String count = tabCount(tab);
			final JLabel label = new JLabel(count == null ? tab.label : tab.label + " " + count, SwingConstants.CENTER);
			label.setFont(FontManager.getRunescapeSmallFont());
			label.setForeground(active ? ColorScheme.BRAND_ORANGE : ColorScheme.LIGHT_GRAY_COLOR);
			label.setCursor(new Cursor(Cursor.HAND_CURSOR));
			label.setBorder(BorderFactory.createMatteBorder(0, 0, 1, 0,
				active ? ColorScheme.BRAND_ORANGE : ColorScheme.MEDIUM_GRAY_COLOR));
			label.addMouseListener(new MouseAdapter()
			{
				@Override
				public void mouseClicked(MouseEvent e)
				{
					activeTab = tab;
					render();
				}
			});
			bar.add(label);
		}
		return bar;
	}

	private String tabCount(SourceTab tab)
	{
		final List<?> list = tab == SourceTab.SPAWNS ? spawnAreas
			: tab == SourceTab.SHOPS ? storeSources : dropSources;
		return list == null ? null : String.valueOf(list.size());
	}

	private JPanel buildPane(SourceTab tab)
	{
		final ScrollList pane = new ScrollList();
		switch (tab)
		{
			case SPAWNS:
				buildSpawnPane(pane);
				break;
			case SHOPS:
				buildShopPane(pane);
				break;
			case DROPS:
				buildDropPane(pane);
				break;
		}
		return pane;
	}

	private void buildSpawnPane(JPanel pane)
	{
		if (spawnAreas == null)
		{
			pane.add(muted("Loading…"));
			return;
		}
		if (spawnAreas.isEmpty())
		{
			pane.add(muted("No reachable ground spawns."));
			return;
		}

		final List<SpawnArea> sorted = new ArrayList<>(spawnAreas);
		if (playerLocation != null)
		{
			sorted.sort(Comparator.comparingLong(this::areaDistSq));
		}

		for (SpawnArea area : sorted)
		{
			pane.add(areaRow(area));
		}

		final List<WorldPoint> all = new ArrayList<>();
		for (SpawnArea a : spawnAreas)
		{
			all.addAll(a.points);
		}
		pane.add(mapLink("Show all on map", all, currentItemName));
	}

	/** One named area (nearest map label); clicking jumps the world map to that area's spawns. */
	private JPanel areaRow(SpawnArea area)
	{
		final JPanel row = clickableRow();
		row.setLayout(new BorderLayout());
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 18));

		final JLabel name = new JLabel(area.name);
		name.setFont(FontManager.getRunescapeSmallFont());
		name.setForeground(ColorScheme.TEXT_COLOR);
		row.add(name, BorderLayout.CENTER);

		row.setToolTipText("Show " + area.name + " on the world map");
		onClick(row, () ->
		{
			if (actions != null)
			{
				actions.showOnMap(currentItemId, area.points, currentItemName + " · " + area.name, false);
			}
		});
		return row;
	}

	/** Squared distance from the player to the nearest tile in the area. */
	private long areaDistSq(SpawnArea area)
	{
		long best = Long.MAX_VALUE;
		for (WorldPoint p : area.points)
		{
			final long dx = p.getX() - playerLocation.getX();
			final long dy = p.getY() - playerLocation.getY();
			final long dist = dx * dx + dy * dy;
			if (dist < best)
			{
				best = dist;
			}
		}
		return best;
	}

	private void buildShopPane(JPanel pane)
