	private static String priceText(StoreSource s)
	{
		final String amount;
		final int v = s.priceValue();
		amount = v == Integer.MAX_VALUE ? s.price : QuantityFormatter.formatNumber(v);
		if (s.currency.isEmpty() || "Coins".equalsIgnoreCase(s.currency))
		{
			return amount + " gp";
