		return amount + " " + s.currency.toLowerCase();
	}

	private static String rateText(DropSource s)
	{
		if ("Always".equalsIgnoreCase(s.rarity))
		{
			return "Always";
		}
		final double p = s.probability;
		if (Double.isNaN(p))
		{
			return s.rarity; // non-numeric word like "Common", or "" if unknown
		}
		if (p >= 1.0)
		{
			return "Always";
		}
		if (p <= 0)
		{
			return s.rarity;
		}
		return "1 / " + Math.max(1, Math.round(1.0 / p));
	}

