	/**
	 * A vertical list of rows (like {@link #plain()}) that, when placed in a {@link JScrollPane},
	 * stretches to the viewport width and scrolls vertically only — so a capped section never grows
	 * a horizontal scrollbar and its rows keep using the full panel width.
	 */
	private static final class ScrollList extends JPanel implements Scrollable
	{
		ScrollList()
		{
			setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
			setAlignmentX(LEFT_ALIGNMENT);
			setOpaque(false);
		}

		@Override
		public Dimension getPreferredScrollableViewportSize()
		{
			return getPreferredSize();
		}

		@Override
		public int getScrollableUnitIncrement(Rectangle visible, int orientation, int direction)
		{
			return 16;
		}

		@Override
		public int getScrollableBlockIncrement(Rectangle visible, int orientation, int direction)
		{
			return visible.height;
		}

		@Override
		public boolean getScrollableTracksViewportWidth()
		{
			return true;
		}

		@Override
		public boolean getScrollableTracksViewportHeight()
		{
			return false;
		}
	}

	/**
	 * If the list is taller than {@link #MAX_SECTION_H} it is wrapped in a fixed-height, vertically
	 * scrollable viewport; otherwise the list is returned as-is (sizes to its content, no scrollbar).
	 */
	private static JComponent scrollCapped(JPanel list)
	{
		list.setAlignmentX(LEFT_ALIGNMENT);
		final Dimension pref = list.getPreferredSize();
		if (pref.height <= MAX_SECTION_H)
		{
			return list;
		}

		final JScrollPane sp = new JScrollPane(list,
			JScrollPane.VERTICAL_SCROLLBAR_AS_NEEDED, JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
		sp.setBorder(BorderFactory.createEmptyBorder());
		sp.setOpaque(false);
		sp.getViewport().setOpaque(false);
		sp.setAlignmentX(LEFT_ALIGNMENT);
		sp.getVerticalScrollBar().setUnitIncrement(16);
		sp.setPreferredSize(new Dimension(pref.width, MAX_SECTION_H));
		sp.setMaximumSize(new Dimension(Integer.MAX_VALUE, MAX_SECTION_H));
		return sp;
	}

	/** A one-line row with a hover highlight and hand cursor, ready for {@link #onClick}. */
