	private static JLabel questRow(String name, boolean done)
	{
		// Colour carries state (white = needed, grey = done); a checkmark tags completed ones.
		final String html = done
			? "✓ " + escape(name)
			: "<font color='#EF4B4B'>•</font> " + escape(name);
		final JLabel label = new JLabel("<html>" + html + "</html>");
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(done ? DONE : Color.WHITE);
		label.setAlignmentX(LEFT_ALIGNMENT);
		return label;
	}

	private static Color rarityColor(DropSource s)
	{
		if ("Always".equalsIgnoreCase(s.rarity))
		{
			return R_ALWAYS;
		}
		final double p = s.probability;
		if (Double.isNaN(p))
		{
			return FAINT;
		}
		if (p >= 1.0)
		{
			return R_ALWAYS;
		}
		if (p >= 1.0 / 10)
		{
			return R_COMMON;
		}
		if (p >= 1.0 / 500)
		{
			return R_UNCOMMON;
		}
		if (p >= 1.0 / 5000)
		{
			return R_RARE;
		}
		return R_VERYRARE;
	}

	private JLabel expander(String text, JPanel target)
	{
		final JLabel label = new JLabel("▸ " + text);
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		label.setCursor(new Cursor(Cursor.HAND_CURSOR));
		label.setAlignmentX(LEFT_ALIGNMENT);
		label.setBorder(BorderFactory.createEmptyBorder(3, 0, 1, 0));
		label.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				final boolean show = !target.isVisible();
				target.setVisible(show);
				label.setText((show ? "▾ " : "▸ ") + text);
				refresh();
			}
		});
		return label;
	}

	private void refresh()
	{
		content.revalidate();
		content.repaint();
	}

	private static String escape(String s)
	{
		return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}

	/** A quest usage of an item with the local player's live state for it. */
	static class QuestFlag
	{
		final String questName;
		final QuestState state;

		QuestFlag(String questName, QuestState state)
		{
			this.questName = questName;
			this.state = state;
		}

		boolean completed()
		{
			return state == QuestState.FINISHED;
		}

		String statusText()
		{
			return state == QuestState.IN_PROGRESS ? "in progress" : "not started";
		}
	}
}

