	@Inject
	private QuestItemDatabase questItemDatabase;

	@Inject
	private DropSourceService dropSourceService;

	@Inject
	private PlaceNameLookup placeNameLookup;

	@Inject
	private SpawnSourceService spawnSourceService;

	@Inject
	private StoreSourceService storeSourceService;

	@Inject
	private ItemRecipeService itemRecipeService;

	@Inject
	private ItemSummaryService itemSummaryService;

	@Inject
	private WorldMapPointManager worldMapPointManager;

	@Inject
	private ChatMessageManager chatMessageManager;

	private ExaminePlusPanel panel;
	private NavigationButton navButton;

	// World map pins for the currently displayed item's spawns (added on user request, cleared on
	// the next examine / logout / shutdown).
	private final List<WorldMapPoint> mapPoints = new CopyOnWriteArrayList<>();

	// Label of the spawn selection currently pinned, so clicking it again toggles the pins off.
	private String pinnedLabel;

	// One entry per examine (FIFO), so our enriched line lands under the right examine text.
	// An empty string means "no line for this examine".
	private final Deque<String> pendingChatLines = new ArrayDeque<>();

	@Provides
	ExaminePlusConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(ExaminePlusConfig.class);
	}

	@Override
	protected void startUp()
	{
		migrateConfig();

		questItemDatabase.load();
		placeNameLookup.load();

		panel = new ExaminePlusPanel();
		panel.setActions(this);

		final BufferedImage icon = ImageUtil.loadImageResource(getClass(), "panel_icon.png");

		navButton = NavigationButton.builder()
			.tooltip("Examine Plus")
			.icon(icon)
			.priority(8)
			.panel(panel)
			.build();

		clientToolbar.addNavigation(navButton);
	}

	@Override
	protected void shutDown()
	{
		clearMapPoints();
		clientToolbar.removeNavigation(navButton);
		navButton = null;
		panel = null;
	}

	/**
	 * Migrate the pre-1.x "showDropSources" toggle to "showItemSources" so users who opted into drop
	 * sources keep the (now broader) sources feature enabled.
	 */
	private void migrateConfig()
	{
		final String old = configManager.getConfiguration("examineplus", "showDropSources");
		if (old != null)
		{
			configManager.setConfiguration("examineplus", "showItemSources", old);
			configManager.unsetConfiguration("examineplus", "showDropSources");
		}
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		if (!"Examine".equals(event.getMenuOption()))
		{
			return;
		}

		final int itemId;
		switch (event.getMenuAction())
		{
			case EXAMINE_ITEM_GROUND:
				itemId = event.getId();
				break;
			case CC_OP_LOW_PRIORITY:
			{
				final int[] qi = findItemFromWidget(event.getParam1(), event.getParam0());
				if (qi == null)
				{
					return;
				}
				itemId = qi[1];
				break;
			}
			default:
				return;
		}

		if (itemId == ItemID.COINS || itemId < 0)
		{
			return;
		}

		onItemExamined(itemId);
	}

	/**
	 * Runs on the client thread (invoked from a menu event). Reads quest state here — it requires
	 * a running client script — then hands rendering to the EDT.
	 */
	private void onItemExamined(int itemId)
	{
		final ItemComposition composition = itemManager.getItemComposition(itemId);
		final String itemName = composition.getName();
		final AsyncBufferedImage icon = itemManager.getImage(itemId);
		final int gePrice = itemManager.getItemPrice(itemId);
		final int alchPrice = composition.getHaPrice();

		final List<Quest> quests = questItemDatabase.getQuestsForItem(itemId);
		final List<ExaminePlusPanel.QuestFlag> flags = new ArrayList<>(quests.size());
		final List<ExaminePlusPanel.QuestFlag> needed = new ArrayList<>();
		for (Quest quest : quests)
		{
			final ExaminePlusPanel.QuestFlag flag = new ExaminePlusPanel.QuestFlag(quest.getName(), questState(quest));
			flags.add(flag);
			if (!flag.completed())
			{
				needed.add(flag);
			}
		}

		// Queue the examine chat line (aligned per-examine; empty = say nothing for this item).
		if (config.showChatVerdict())
		{
			pendingChatLines.addLast(buildChatLine(needed));
		}

		// A new examine supersedes any pins left from the previous item.
		clearMapPoints();

		final boolean autoOpen = config.openPanelOnExamine();
		final boolean showSources = config.showItemSources();
		SwingUtilities.invokeLater(() ->
		{
			if (panel == null)
			{
				return;
			}
			panel.displayItem(itemId, itemName, icon, gePrice, alchPrice, flags, showSources);
			if (autoOpen && navButton != null)
			{
				clientToolbar.openPanel(navButton);
			}
		});

		if (showSources)
		{
			// Async wiki lookups; results may arrive on an OkHttp thread, so marshal back to the EDT.
			dropSourceService.lookup(itemName, (name, sources) ->
				SwingUtilities.invokeLater(() ->
				{
					if (panel != null)
					{
						panel.setDrops(itemId, sources);
					}
				}));
			// Snapshot the player's tile now (client thread) so the panel can sort spawns by distance.
			final WorldPoint playerLoc = client.getLocalPlayer() != null
				? client.getLocalPlayer().getWorldLocation() : null;
			spawnSourceService.lookup(itemName, (name, sources) ->
				SwingUtilities.invokeLater(() ->
				{
					if (panel != null)
					{
						panel.setSpawns(itemId, sources, playerLoc);
					}
				}));
			storeSourceService.lookup(itemName, (name, sources) ->
				SwingUtilities.invokeLater(() ->
				{
					if (panel != null)
					{
						panel.setStores(itemId, sources);
					}
				}));
			// What this item helps make (item is a material).
			itemRecipeService.lookupUses(itemName, (name, recipes) ->
				SwingUtilities.invokeLater(() ->
				{
					if (panel != null)
					{
						panel.setUses(itemId, recipes);
					}
				}));
			// How to make this item (item is the output).
			itemRecipeService.lookupRecipe(itemName, (name, recipes) ->
				SwingUtilities.invokeLater(() ->
				{
					if (panel != null)
					{
						panel.setRecipe(itemId, recipes);
					}
				}));
			// One-line wiki description of what the item is.
			itemSummaryService.lookup(itemName, (name, summary) ->
				SwingUtilities.invokeLater(() ->
				{
					if (panel != null)
					{
						panel.setSummary(itemId, summary);
					}
				}));
		}
	}

	@Override
	public void showOnMap(int itemId, List<WorldPoint> points, String label, boolean toggle)
	{
		clientThread.invoke(() ->
		{
			// "Show all" toggles: clicking it again with the same selection clears the pins.
			if (toggle && label != null && label.equals(pinnedLabel))
			{
				clearMapPoints();
				return;
			}

			clearMapPoints();
			if (points == null || points.isEmpty())
			{
				return;
			}
			final BufferedImage image = itemManager.getImage(itemId);
			for (WorldPoint wp : points)
			{
				final WorldMapPoint mapPoint = WorldMapPoint.builder()
					.worldPoint(wp)
					.image(image)
					.jumpOnClick(true)
					.name(label)
					.tooltip(label)
					.build();
				worldMapPointManager.add(mapPoint);
				mapPoints.add(mapPoint);
			}
			pinnedLabel = label;

			// Recenter the world map (only takes effect while the map is open) on the spawn nearest the
			// player — most useful for "where's the closest one". Points are already surface-filtered.
			client.getWorldMap().setWorldMapPositionTarget(nearestToPlayer(points));

			final Widget map = client.getWidget(InterfaceID.Worldmap.MAP_CONTAINER);
			if (map == null || map.isHidden())
			{
				final String line = new ChatMessageBuilder()
					.append(ChatColorType.NORMAL)
					.append("Examine Plus: pinned " + points.size() + " spawn" + (points.size() == 1 ? "" : "s")
						+ " — open the world map to view.")
					.build();
				chatMessageManager.queue(QueuedMessage.builder()
					.type(ChatMessageType.GAMEMESSAGE)
					.runeLiteFormattedMessage(line)
					.build());
			}
		});
	}

	/** The spawn tile closest to the player (2D squared distance); the first tile if location unknown. */
	private WorldPoint nearestToPlayer(List<WorldPoint> points)
	{
		final WorldPoint from = client.getLocalPlayer() != null
			? client.getLocalPlayer().getWorldLocation() : null;
		if (from == null)
		{
			return points.get(0);
		}
		WorldPoint best = points.get(0);
		long bestDist = Long.MAX_VALUE;
		for (WorldPoint wp : points)
		{
			final long dx = wp.getX() - from.getX();
			final long dy = wp.getY() - from.getY();
			final long dist = dx * dx + dy * dy;
			if (dist < bestDist)
			{
				bestDist = dist;
				best = wp;
			}
		}
		return best;
	}

	@Override
	public void openMonsterWiki(String monsterName)
	{
		openWiki(monsterName);
	}

	@Override
	public void openItemWiki(String itemName)
	{
		openWiki(itemName);
	}

	private static void openWiki(String pageName)
	{
		if (pageName == null || pageName.trim().isEmpty())
		{
			return;
		}
		LinkBrowser.browse("https://oldschool.runescape.wiki/w/" + pageName.trim().replace(' ', '_'));
	}

	private void clearMapPoints()
	{
		for (WorldMapPoint mapPoint : mapPoints)
		{
			worldMapPointManager.remove(mapPoint);
		}
		mapPoints.clear();
		pinnedLabel = null;
	}

	private static String buildChatLine(List<ExaminePlusPanel.QuestFlag> needed)
	{
		if (needed.isEmpty())
		{
			return "";
		}

		final ChatMessageBuilder builder = new ChatMessageBuilder()
			.append(ChatColorType.NORMAL)
			.append("Examine Plus: ");

		if (needed.size() == 1)
		{
			final ExaminePlusPanel.QuestFlag q = needed.get(0);
			builder.append("Keep — needed for ")
				.append(ChatColorType.HIGHLIGHT)
				.append(q.questName)
				.append(ChatColorType.NORMAL)
				.append(" (" + q.statusText() + ").");
		}
		else
		{
			builder.append("Keep — needed for ")
				.append(ChatColorType.HIGHLIGHT)
				.append(Integer.toString(needed.size()))
				.append(ChatColorType.NORMAL)
				.append(" quests you haven't completed.");
		}

		return builder.build();
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() != ChatMessageType.ITEM_EXAMINE || pendingChatLines.isEmpty())
		{
			return;
		}

		final String line = pendingChatLines.pollFirst();
		if (line != null && !line.isEmpty())
		{
			chatMessageManager.queue(QueuedMessage.builder()
				.type(ChatMessageType.ITEM_EXAMINE)
				.runeLiteFormattedMessage(line)
				.build());
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		pendingChatLines.clear();

		final GameState state = event.getGameState();
		if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING || state == GameState.CONNECTION_LOST)
		{
			clearMapPoints();
		}
	}

	private QuestState questState(Quest quest)
	{
		try
		{
			return quest.getState(client);
		}
		catch (Exception e)
		{
			// getState runs a client script; be defensive if called in an unexpected state.
			log.debug("Failed to read state for quest {}", quest, e);
			return QuestState.NOT_STARTED;
		}
	}

	/**
	 * Resolve the item id from the widget that was examined (inventory, worn, bank, shop, etc.).
	 * Mirrors the core Examine plugin's widget resolution.
	 */
	private int[] findItemFromWidget(int widgetId, int childIdx)
	{
		final int widgetGroup = WidgetUtil.componentToInterface(widgetId);
		final Widget widget = client.getWidget(widgetId);
		if (widget == null)
		{
			return null;
		}

		if (InterfaceID.WORNITEMS == widgetGroup)
		{
			final Widget widgetItem = widget.getChild(1);
			if (widgetItem != null)
			{
				return new int[]{widgetItem.getItemQuantity(), widgetItem.getItemId()};
			}
		}
		else if (InterfaceID.SMITHING == widgetGroup)
		{
			final Widget widgetItem = widget.getChild(2);
			if (widgetItem != null)
			{
				return new int[]{widgetItem.getItemQuantity(), widgetItem.getItemId()};
			}
		}
		else if (InterfaceID.SHOPMAIN == widgetGroup)
		{
			final Widget widgetItem = widget.getChild(childIdx);
			if (widgetItem != null)
			{
				return new int[]{1, widgetItem.getItemId()};
			}
		}
		else
		{
			final Widget widgetItem = widget.getChild(childIdx);
			if (widgetItem != null && widgetItem.getItemId() > -1)
			{
				return new int[]{widgetItem.getItemQuantity(), widgetItem.getItemId()};
			}
		}

		return null;
	}
}

package com.examineplus;

import java.util.List;

/**
 * A single crafting/production recipe parsed from the OSRS Wiki 'recipe' bucket's {@code production_json}.
 * Used two ways: for "what this item makes" (the examined item is one of the {@link #materials}) and for
 * "how to make this item" (the examined item is the {@link #output}). All fields default to safe/empty
 * values rather than null so the panel never has to null-check them.
 */
class ItemRecipe
{
	final String output;          // output item name
	final String outputQuantity;  // amount produced, e.g. "1" or "12"
	final List<Ingredient> materials;
	final List<SkillReq> skills;  // skill(s)/level(s) required to make it
	final String tools;           // e.g. "Chisel", or "" if none
	final String facility;        // e.g. "Anvil", or "" if none
	final boolean members;        // members-only recipe

	ItemRecipe(String output, String outputQuantity, List<Ingredient> materials,
		List<SkillReq> skills, String tools, String facility, boolean members)
	{
		this.output = output;
		this.outputQuantity = outputQuantity;
		this.materials = materials;
		this.skills = skills;
		this.tools = tools;
		this.facility = facility;
		this.members = members;
	}

	/** One input material of a recipe. */
	static class Ingredient
	{
		final String name;
		final String quantity; // e.g. "1", "4"

		Ingredient(String name, String quantity)
		{
			this.name = name;
			this.quantity = quantity;
		}
	}

	/** A skill + level requirement to make the item. */
	static class SkillReq
	{
		final String skill;
		final String level; // e.g. "42"; may be "" or "0" when the recipe grants xp but has no level gate

		SkillReq(String skill, String level)
		{
			this.skill = skill;
			this.level = level;
		}
	}
}

package com.examineplus;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

/**
 * Fetches crafting/production recipes from the OSRS Wiki 'recipe' bucket. Each recipe's ingredients,
 * skill/level requirements and output are packed into a per-row {@code production_json} blob (the
 * top-level {@code uses_material}/{@code uses_skill} columns are only for filtering). Two lookups are
 * exposed, both querying the same bucket with a different {@code where}:
 * <ul>
 *   <li>{@link #lookupUses} — recipes where the examined item is a <b>material</b>, i.e. "what it makes".</li>
 *   <li>{@link #lookupRecipe} — recipes whose <b>output</b> is the examined item, i.e. "how to make this".</li>
 * </ul>
 * All network calls are async (OkHttp enqueue); results are cached per item name for the session.
 */
@Slf4j
@Singleton
class ItemRecipeService
{
	private static final HttpUrl API = HttpUrl.get("https://oldschool.runescape.wiki/api.php");
	private static final String USER_AGENT = "examine-plus (RuneLite plugin; https://github.com/nikolajs/examine-plus)";

	private final OkHttpClient httpClient;
	private final Gson gson;

	// "Uses" (item is a material) and "recipe" (item is the output) are cached separately per item name.
	private final Map<String, List<ItemRecipe>> usesCache = new ConcurrentHashMap<>();
	private final Map<String, List<ItemRecipe>> recipeCache = new ConcurrentHashMap<>();

	@FunctionalInterface
	interface Callback2
	{
		void onResult(String itemName, List<ItemRecipe> recipes);
	}

	/** Post-processes the flat list of parsed recipes (filter/dedupe/sort) for a given lookup. */
	private interface PostParser
	{
		List<ItemRecipe> apply(String itemName, List<ItemRecipe> recipes);
	}

	@Inject
	ItemRecipeService(OkHttpClient httpClient, Gson gson)
	{
		this.httpClient = httpClient;
		this.gson = gson;
	}

	/** Recipes in which the examined item is an ingredient — the products it helps make. */
	void lookupUses(String itemName, Callback2 callback)
	{
		query("uses_material", itemName, 200, usesCache, ItemRecipeService::dedupeByOutput, callback);
	}

	/** The examined item's own recipe(s) — how it is made. */
	void lookupRecipe(String itemName, Callback2 callback)
	{
		query("page_name", itemName, 20, recipeCache, ItemRecipeService::onlyOutput, callback);
	}

	private void query(String whereField, String itemName, int limit,
		Map<String, List<ItemRecipe>> cache, PostParser post, Callback2 callback)
	{
		final List<ItemRecipe> cached = cache.get(itemName);
		if (cached != null)
		{
			callback.onResult(itemName, cached);
			return;
		}

		// production_json carries everything (materials, skills, tools, facility, members, output);
		// double-quote the value so names with apostrophes (e.g. "Zamorak's grapes") don't break the Lua.
		final String q = "bucket('recipe').select('page_name','production_json')"
			+ ".where('" + whereField + "',\"" + itemName.replace("\"", "") + "\").limit(" + limit + ").run()";

		final HttpUrl url = API.newBuilder()
			.addQueryParameter("action", "bucket")
			.addQueryParameter("format", "json")
			.addQueryParameter("query", q)
			.build();

		final Request request = new Request.Builder()
			.url(url)
			.header("User-Agent", USER_AGENT)
			.build();

		httpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("Recipe lookup ({}) failed for {}", whereField, itemName, e);
				callback.onResult(itemName, Collections.emptyList());
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (ResponseBody body = response.body())
				{
					if (!response.isSuccessful() || body == null)
					{
						callback.onResult(itemName, Collections.emptyList());
						return;
					}

					final List<ItemRecipe> recipes = post.apply(itemName, parse(body.string()));
					cache.put(itemName, recipes);
					callback.onResult(itemName, recipes);
				}
				catch (Exception e)
				{
					log.debug("Failed to parse recipes ({}) for {}", whereField, itemName, e);
					callback.onResult(itemName, Collections.emptyList());
				}
			}
		});
	}

	private List<ItemRecipe> parse(String responseBody)
	{
		final JsonObject root = gson.fromJson(responseBody, JsonObject.class);
		if (root == null || root.has("error") || !root.has("bucket"))
		{
			return Collections.emptyList();
		}

		final List<ItemRecipe> recipes = new ArrayList<>();
		for (JsonElement rowEl : root.getAsJsonArray("bucket"))
		{
			if (!rowEl.isJsonObject())
			{
				continue;
			}
			final ItemRecipe recipe = parseRow(rowEl.getAsJsonObject());
			if (recipe != null)
			{
				recipes.add(recipe);
			}
		}
		return recipes;
	}

	/** Parse one bucket row's production_json into an {@link ItemRecipe}; null if it has no usable output. */
	private ItemRecipe parseRow(JsonObject row)
	{
		final String blob = str(row, "production_json");
		if (blob.isEmpty())
		{
			return null;
		}

		final JsonObject p;
		try
		{
			p = gson.fromJson(blob, JsonObject.class);
		}
		catch (Exception e)
		{
			return null;
		}
		if (p == null)
		{
			return null;
		}

		String output = "";
		String outputQty = "";
		final JsonElement outEl = p.get("output");
		if (outEl != null && outEl.isJsonObject())
		{
			final JsonObject out = outEl.getAsJsonObject();
			output = str(out, "name");
			outputQty = str(out, "quantity");
		}
		if (output.isEmpty())
		{
			// Fall back to the page name, which is normally the output item's article.
			output = str(row, "page_name");
		}
		if (output.isEmpty())
		{
			return null;
		}

		final List<ItemRecipe.Ingredient> materials = new ArrayList<>();
		final JsonElement matsEl = p.get("materials");
		if (matsEl != null && matsEl.isJsonArray())
		{
			for (JsonElement mEl : matsEl.getAsJsonArray())
			{
				if (!mEl.isJsonObject())
				{
					continue;
				}
				final JsonObject m = mEl.getAsJsonObject();
				final String name = str(m, "name");
				if (!name.isEmpty())
				{
					materials.add(new ItemRecipe.Ingredient(name, str(m, "quantity")));
				}
			}
		}

		final List<ItemRecipe.SkillReq> skills = new ArrayList<>();
		final JsonElement skillsEl = p.get("skills");
		if (skillsEl != null && skillsEl.isJsonArray())
		{
			for (JsonElement sEl : skillsEl.getAsJsonArray())
			{
				if (!sEl.isJsonObject())
				{
					continue;
				}
				final JsonObject s = sEl.getAsJsonObject();
				final String name = str(s, "name");
				if (!name.isEmpty())
				{
					skills.add(new ItemRecipe.SkillReq(name, str(s, "level")));
				}
			}
		}

		boolean members = false;
		final JsonElement memEl = p.get("members");
		if (memEl != null && memEl.isJsonPrimitive())
		{
			try
			{
				members = memEl.getAsBoolean();
			}
			catch (Exception ignored)
			{
				// leave false
			}
		}

		return new ItemRecipe(output, outputQty, materials, skills,
			str(p, "tools"), str(p, "facilities"), members);
	}

	/** For "uses": one entry per distinct product, first-seen order preserved, output name sorted A-Z. */
	private static List<ItemRecipe> dedupeByOutput(String itemName, List<ItemRecipe> recipes)
	{
		final Map<String, ItemRecipe> byOutput = new LinkedHashMap<>();
		for (ItemRecipe r : recipes)
		{
			// Skip a self-referential row (item listed as making itself) and duplicates.
			if (r.output.equalsIgnoreCase(itemName))
			{
				continue;
			}
			byOutput.putIfAbsent(r.output.toLowerCase(), r);
		}
		final List<ItemRecipe> out = new ArrayList<>(byOutput.values());
		out.sort((a, b) -> a.output.compareToIgnoreCase(b.output));
		return Collections.unmodifiableList(out);
	}

	/** For "how to make": keep only recipes whose output actually is the examined item (multi-item pages). */
	private static List<ItemRecipe> onlyOutput(String itemName, List<ItemRecipe> recipes)
	{
		final List<ItemRecipe> out = new ArrayList<>();
		for (ItemRecipe r : recipes)
		{
			if (r.output.equalsIgnoreCase(itemName))
			{
				out.add(r);
			}
		}
		return Collections.unmodifiableList(out);
	}

	private static String str(JsonObject o, String key)
	{
		final JsonElement e = o.get(key);
		if (e == null || e.isJsonNull())
		{
			return "";
		}
		try
		{
			return e.isJsonArray() ? arrayFirst(e.getAsJsonArray()) : e.getAsString();
		}
		catch (Exception ex)
		{
			return "";
		}
	}

	private static String arrayFirst(JsonArray arr)
	{
		return arr.size() == 0 ? "" : arr.get(0).getAsString();
	}
}

package com.examineplus;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

/**
 * Fetches a one-line plain-English summary of an item — the first sentence of its OSRS Wiki article,
 * via the MediaWiki TextExtracts API ({@code prop=extracts&exintro&explaintext&exsentences=1}). This
 * fills in for in-game examine text that describes flavour rather than function, and (as a bonus) the
 * intro sentence commonly states use/equip requirements in prose (e.g. "…requiring level 40 Attack to
 * wield."). Cached per item name for the session.
 */
@Slf4j
@Singleton
class ItemSummaryService
{
	private static final HttpUrl API = HttpUrl.get("https://oldschool.runescape.wiki/api.php");
	private static final String USER_AGENT = "examine-plus (RuneLite plugin; https://github.com/nikolajs/examine-plus)";
	private static final int MAX_LEN = 300;

	private final OkHttpClient httpClient;
	private final Gson gson;

	// Empty string is a valid cached result (no summary); ConcurrentHashMap disallows null values.
	private final Map<String, String> cache = new ConcurrentHashMap<>();

	@FunctionalInterface
	interface Callback2
	{
		void onResult(String itemName, String summary);
	}

	@Inject
	ItemSummaryService(OkHttpClient httpClient, Gson gson)
	{
		this.httpClient = httpClient;
		this.gson = gson;
	}

	void lookup(String itemName, Callback2 callback)
	{
		final String cached = cache.get(itemName);
		if (cached != null)
		{
			callback.onResult(itemName, cached);
			return;
		}

		final HttpUrl url = API.newBuilder()
			.addQueryParameter("action", "query")
			.addQueryParameter("format", "json")
			.addQueryParameter("prop", "extracts")
			.addQueryParameter("exintro", "1")
			.addQueryParameter("explaintext", "1")
			.addQueryParameter("exsentences", "1")
			.addQueryParameter("redirects", "1")
			.addQueryParameter("titles", itemName)
			.build();

		final Request request = new Request.Builder()
			.url(url)
			.header("User-Agent", USER_AGENT)
			.build();

		httpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("Summary lookup failed for {}", itemName, e);
				callback.onResult(itemName, "");
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (ResponseBody body = response.body())
				{
					if (!response.isSuccessful() || body == null)
					{
						callback.onResult(itemName, "");
						return;
					}

					final String summary = parse(body.string());
					cache.put(itemName, summary);
					callback.onResult(itemName, summary);
				}
				catch (Exception e)
				{
					log.debug("Failed to parse summary for {}", itemName, e);
					callback.onResult(itemName, "");
				}
			}
		});
	}

	private String parse(String responseBody)
	{
		final JsonObject root = gson.fromJson(responseBody, JsonObject.class);
		if (root == null || !root.has("query"))
		{
			return "";
		}
		final JsonObject query = root.getAsJsonObject("query");
		if (query == null || !query.has("pages"))
		{
			return "";
		}
		final JsonObject pages = query.getAsJsonObject("pages");
		if (pages == null)
		{
			return "";
		}

		for (Map.Entry<String, JsonElement> entry : pages.entrySet())
		{
			final JsonElement pageEl = entry.getValue();
			if (pageEl == null || !pageEl.isJsonObject())
			{
				continue;
			}
			final JsonElement extractEl = pageEl.getAsJsonObject().get("extract");
			if (extractEl == null || extractEl.isJsonNull())
			{
				continue;
			}
			final String extract = clean(extractEl.getAsString());
			if (!extract.isEmpty())
			{
				return extract;
			}
		}
		return "";
	}

	/** Collapse whitespace and cap the length so a stray multi-sentence extract can't dominate the panel. */
	private static String clean(String raw)
	{
		String s = raw.replaceAll("\\s+", " ").trim();
		if (s.length() > MAX_LEN)
		{
			s = s.substring(0, MAX_LEN).trim() + "…";
		}
		return s;
	}
}

package com.examineplus;

import com.google.gson.Gson;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.coords.WorldPoint;

/**
 * Reverse-geocodes a {@link WorldPoint} to the nearest OSRS map label (e.g. "Draynor Manor").
 * Backed by a bundled snapshot of the game's world-map text labels derived from the OSRS Wiki
 * (User:Microbrews/Map labels, CC BY-NC-SA). Loaded once; lookups are a linear nearest-neighbour
 * scan (~1k labels — negligible).
 */
@Slf4j
@Singleton
class PlaceNameLookup
{
	private static class Label
	{
		String n;
		int x;
		int y;
	}

	private final Gson gson;
	private Label[] labels = new Label[0];

	@Inject
	PlaceNameLookup(Gson gson)
	{
		this.gson = gson;
	}

	void load()
	{
		try (InputStream in = getClass().getResourceAsStream("map_labels.json"))
		{
			if (in == null)
			{
				log.warn("map_labels.json resource missing");
				return;
			}
			final Label[] loaded = gson.fromJson(new InputStreamReader(in, StandardCharsets.UTF_8), Label[].class);
			if (loaded != null)
			{
				labels = loaded;
			}
			log.debug("Loaded {} map labels", labels.length);
		}
		catch (Exception e)
		{
			log.warn("Failed to load map labels", e);
		}
	}

	/** Nearest label name by 2D distance, or "Unknown area" if none are loaded. */
	String nearest(WorldPoint wp)
	{
		Label best = null;
		long bestDist = Long.MAX_VALUE;
		for (Label label : labels)
		{
			final long dx = label.x - wp.getX();
			final long dy = label.y - wp.getY();
			final long dist = dx * dx + dy * dy;
			if (dist < bestDist)
			{
				bestDist = dist;
				best = label;
			}
		}
		return best == null ? "Unknown area" : best.n;
	}
}

package com.examineplus;

import com.google.gson.Gson;
import com.google.gson.annotations.SerializedName;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Quest;

/**
 * Loads the bundled item -> quests mapping from resources and exposes lookups by item id.
 *
 * The resource is a JSON document of the shape:
 * <pre>
 * { "version": 1, "items": { "&lt;itemId&gt;": ["QUEST_ENUM_NAME", ...] } }
 * </pre>
 * where each string is a {@link net.runelite.api.Quest} enum constant name.
 */
@Slf4j
@Singleton
class QuestItemDatabase
{
	private static final String RESOURCE = "quest_items.json";

	private final Gson gson;

	// itemId -> quests that require the item. Unmodifiable once loaded.
	private Map<Integer, List<Quest>> itemToQuests = Collections.emptyMap();

	@Inject
	QuestItemDatabase(Gson gson)
	{
		this.gson = gson;
	}

	void load()
	{
		try (InputStream in = QuestItemDatabase.class.getResourceAsStream(RESOURCE))
		{
			if (in == null)
			{
				log.debug("Quest item dataset '{}' not found on classpath; quest flagging disabled", RESOURCE);
				return;
			}

			final QuestItemFile file = gson.fromJson(new InputStreamReader(in, StandardCharsets.UTF_8), QuestItemFile.class);
			if (file == null || file.items == null)
			{
				log.debug("Quest item dataset is empty or malformed");
				return;
			}

			final Map<Integer, List<Quest>> parsed = new HashMap<>();
			int skippedQuests = 0;
			for (Map.Entry<String, List<String>> entry : file.items.entrySet())
			{
				final int itemId;
				try
				{
					itemId = Integer.parseInt(entry.getKey());
				}
				catch (NumberFormatException e)
				{
					log.debug("Skipping non-numeric item id key: {}", entry.getKey());
					continue;
				}

				if (entry.getValue() == null)
				{
					continue;
				}

				final java.util.List<Quest> quests = new java.util.ArrayList<>();
				for (String questName : entry.getValue())
				{
					try
					{
						quests.add(Quest.valueOf(questName));
					}
					catch (IllegalArgumentException e)
					{
						// Not a valid Quest enum constant in this client version; skip it.
						skippedQuests++;
					}
				}

				if (!quests.isEmpty())
				{
					parsed.put(itemId, Collections.unmodifiableList(quests));
				}
			}

			itemToQuests = Collections.unmodifiableMap(parsed);
			log.debug("Loaded quest item dataset: {} items ({} unknown quest names skipped)", itemToQuests.size(), skippedQuests);
		}
		catch (Exception e)
		{
			log.warn("Failed to load quest item dataset", e);
		}
	}

	/**
	 * @return the quests that require the given item, or an empty list if none are known.
	 */
	List<Quest> getQuestsForItem(int itemId)
	{
		return itemToQuests.getOrDefault(itemId, Collections.emptyList());
	}

	private static class QuestItemFile
	{
		@SerializedName("version")
		int version;

		@SerializedName("items")
		Map<String, List<String>> items;
	}
}

