package com.examineplus;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.coords.WorldPoint;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

/**
 * Fetches item ground-spawn tiles from the OSRS Wiki 'locline' bucket as a flat, de-duplicated list
 * of surface {@link WorldPoint}s. The bucket's only location label is the coarse Leagues "region"
 * (with junk values like "general"/"no" that mean nothing to a player), so we don't group by it —
 * the world-map pins do the locating. Underground/instanced tiles (y ~9000-10000) are dropped since
 * the surface world map can't navigate to them. Results are cached per item name for the session.
 */
@Slf4j
@Singleton
class SpawnSourceService
{
	private static final HttpUrl API = HttpUrl.get("https://oldschool.runescape.wiki/api.php");
	private static final String USER_AGENT = "examine-plus (RuneLite plugin; https://github.com/nikolajs/examine-plus)";

	// Coordinate strings vary: "2766,3441", "x:2357,y:10325", "1411, 2858" — grab the first two integers.
	private static final Pattern INT = Pattern.compile("-?\\d+");

	// Overworld surface tiles sit below this Y; underground/instanced areas use ~9000-10000 and the
	// surface world map can't navigate to them (it bugs out).
	private static final int SURFACE_MAX_Y = 6400;

	private final OkHttpClient httpClient;
	private final Gson gson;
	private final PlaceNameLookup placeNames;

	private final Map<String, List<SpawnArea>> cache = new ConcurrentHashMap<>();

	@FunctionalInterface
	interface Callback2
	{
		void onResult(String itemName, List<SpawnArea> areas);
	}

	@Inject
	SpawnSourceService(OkHttpClient httpClient, Gson gson, PlaceNameLookup placeNames)
	{
		this.httpClient = httpClient;
		this.gson = gson;
		this.placeNames = placeNames;
	}

	void lookup(String itemName, Callback2 callback)
	{
		final List<SpawnArea> cached = cache.get(itemName);
		if (cached != null)
		{
			callback.onResult(itemName, cached);
			return;
		}

		final String query = "bucket('locline').select('page_name','coordinates','plane')"
			+ ".where('page_name',\"" + itemName.replace("\"", "") + "\").limit(200).run()";

		final HttpUrl url = API.newBuilder()
			.addQueryParameter("action", "bucket")
			.addQueryParameter("format", "json")
			.addQueryParameter("query", query)
			.build();

		final Request request = new Request.Builder()
			.url(url)
			.header("User-Agent", USER_AGENT)
			.build();

		httpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("Spawn lookup failed for {}", itemName, e);
				callback.onResult(itemName, Collections.emptyList());
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (ResponseBody body = response.body())
				{
					if (!response.isSuccessful() || body == null)
					{
						callback.onResult(itemName, Collections.emptyList());
						return;
					}

					final List<SpawnArea> areas = parse(body.string());
					cache.put(itemName, areas);
					callback.onResult(itemName, areas);
				}
				catch (Exception e)
				{
					log.debug("Failed to parse spawns for {}", itemName, e);
					callback.onResult(itemName, Collections.emptyList());
				}
			}
		});
	}

	private List<SpawnArea> parse(String responseBody)
	{
		final JsonObject root = gson.fromJson(responseBody, JsonObject.class);
		if (root == null || root.has("error") || !root.has("bucket"))
		{
			return Collections.emptyList();
		}

		// De-duplicate coincident tiles; preserve first-seen order.
		final LinkedHashSet<WorldPoint> points = new LinkedHashSet<>();

		for (JsonElement rowEl : root.getAsJsonArray("bucket"))
		{
			if (!rowEl.isJsonObject())
			{
				continue;
			}
			final JsonObject row = rowEl.getAsJsonObject();
			final int plane = optInt(row.get("plane"));

			for (JsonElement coordEl : coordinateStrings(row.get("coordinates")))
			{
				final WorldPoint wp = parseCoord(coordEl.getAsString(), plane);
				// Keep only surface tiles the world map can actually navigate to. Underground and
				// instanced spawns use offset coordinates (y ~9000-10000) — pinning/centering on them
				// bugs the map out.
				if (wp != null && isSurface(wp))
				{
					points.add(wp);
				}
			}
		}

		// Group tiles under the nearest named place (e.g. "Draynor Manor"), preserving first-seen order.
		final Map<String, List<WorldPoint>> byArea = new LinkedHashMap<>();
		for (WorldPoint wp : points)
		{
			byArea.computeIfAbsent(placeNames.nearest(wp), k -> new ArrayList<>()).add(wp);
		}

		final List<SpawnArea> areas = new ArrayList<>(byArea.size());
		for (Map.Entry<String, List<WorldPoint>> e : byArea.entrySet())
		{
			areas.add(new SpawnArea(e.getKey(), e.getValue()));
		}
		return Collections.unmodifiableList(areas);
	}

	private static WorldPoint parseCoord(String s, int plane)
	{
		if (s == null)
		{
			return null;
		}
		final Matcher m = INT.matcher(s);
		if (!m.find())
		{
			return null;
		}
		final int x = Integer.parseInt(m.group());
		if (!m.find())
		{
			return null;
		}
		final int y = Integer.parseInt(m.group());
		return new WorldPoint(x, y, plane);
	}

	private static boolean isSurface(WorldPoint wp)
	{
		return wp.getX() > 0 && wp.getY() > 0 && wp.getY() < SURFACE_MAX_Y;
	}

	/** coordinates may be a JSON array of strings or (rarely) a single string. */
	private static Iterable<JsonElement> coordinateStrings(JsonElement el)
	{
		if (el == null || el.isJsonNull())
		{
			return Collections.emptyList();
		}
		if (el.isJsonArray())
		{
			return el.getAsJsonArray();
		}
		final JsonArray one = new JsonArray();
		one.add(el);
		return one;
	}

	private static int optInt(JsonElement el)
	{
		try
		{
			return (el == null || el.isJsonNull()) ? 0 : el.getAsInt();
		}
		catch (NumberFormatException e)
		{
			return 0;
		}
	}
}

package com.examineplus;

/**
 * A single shop that sells an item, parsed from the OSRS Wiki 'storeline' bucket.
 */
class StoreSource
{
	final String shop;      // shop name, trailing punctuation stripped
	final String price;     // price the shop sells at (what the player pays), raw string
	final String stock;     // base stock quantity, raw string
	final String currency;  // e.g. "Coins", "Tokkul"
	final boolean members;  // members-only shop
	final String location;  // human location text, wiki markup stripped ("" if unknown)

	StoreSource(String shop, String price, String stock, String currency, boolean members, String location)
	{
		this.shop = shop;
		this.price = price;
		this.stock = stock;
		this.currency = currency;
		this.members = members;
		this.location = location;
	}

	/**
	 * Parsed sell price for sorting; Integer.MAX_VALUE if not numeric so unknowns sort last.
	 */
	int priceValue()
	{
		try
		{
			return Integer.parseInt(price.trim().replace(",", ""));
		}
		catch (NumberFormatException e)
		{
			return Integer.MAX_VALUE;
		}
	}
}

