/**
 * Fetches the shops that sell an item from the OSRS Wiki 'storeline' bucket. Members flag and
 * location live inside a nested JSON blob (sold_item_json) rather than top-level columns. Shops
 * appear once per stock variant, so results are de-duplicated by shop name. Cached per item name.
 */
@Slf4j
@Singleton
class StoreSourceService
{
	private static final HttpUrl API = HttpUrl.get("https://oldschool.runescape.wiki/api.php");
	private static final String USER_AGENT = "examine-plus (RuneLite plugin; https://github.com/nikolajs/examine-plus)";

	private final OkHttpClient httpClient;
	private final Gson gson;

	private final Map<String, List<StoreSource>> cache = new ConcurrentHashMap<>();

	@FunctionalInterface
	interface Callback2
	{
		void onResult(String itemName, List<StoreSource> sources);
	}

	@Inject
	StoreSourceService(OkHttpClient httpClient, Gson gson)
	{
		this.httpClient = httpClient;
		this.gson = gson;
	}

	void lookup(String itemName, Callback2 callback)
	{
		final List<StoreSource> cached = cache.get(itemName);
		if (cached != null)
		{
			callback.onResult(itemName, cached);
			return;
		}

		final String query = "bucket('storeline').select('sold_item','sold_by','store_sell_price',"
			+ "'store_stock','store_currency','sold_item_json')"
			+ ".where('sold_item',\"" + itemName.replace("\"", "") + "\").limit(100).run()";

		final HttpUrl url = API.newBuilder()
			.addQueryParameter("action", "bucket")
			.addQueryParameter("format", "json")
			.addQueryParameter("query", query)
			.build();

		final Request request = new Request.Builder()
			.url(url)
			.header("User-Agent", USER_AGENT)
			.build();

		httpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("Store lookup failed for {}", itemName, e);
				callback.onResult(itemName, Collections.emptyList());
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (ResponseBody body = response.body())
				{
					if (!response.isSuccessful() || body == null)
					{
						callback.onResult(itemName, Collections.emptyList());
						return;
					}

					final List<StoreSource> sources = parse(body.string());
					cache.put(itemName, sources);
					callback.onResult(itemName, sources);
				}
				catch (Exception e)
				{
					log.debug("Failed to parse stores for {}", itemName, e);
					callback.onResult(itemName, Collections.emptyList());
				}
			}
		});
	}

	private List<StoreSource> parse(String responseBody)
	{
		final JsonObject root = gson.fromJson(responseBody, JsonObject.class);
		if (root == null || root.has("error") || !root.has("bucket"))
		{
			return Collections.emptyList();
		}

		// One entry per shop; the wiki lists a shop repeatedly for stock/quest variants.
		final Map<String, StoreSource> byShop = new LinkedHashMap<>();

		for (JsonElement rowEl : root.getAsJsonArray("bucket"))
		{
			if (!rowEl.isJsonObject())
			{
				continue;
			}
			final JsonObject row = rowEl.getAsJsonObject();

			final String shop = cleanShop(str(row, "sold_by"));
			if (shop.isEmpty() || byShop.containsKey(shop))
			{
				continue;
			}

			boolean members = false;
			String location = "";
			final String blob = str(row, "sold_item_json");
			if (!blob.isEmpty())
			{
				try
				{
					final JsonObject j = gson.fromJson(blob, JsonObject.class);
					if (j != null)
					{
						members = "Yes".equalsIgnoreCase(str(j, "Members"));
						location = cleanLocation(str(j, "Location"));
					}
				}
				catch (Exception ignored)
				{
					// nested blob missing/invalid — leave members/location at defaults
				}
			}

			byShop.put(shop, new StoreSource(
				shop,
				str(row, "store_sell_price"),
				str(row, "store_stock"),
				str(row, "store_currency"),
				members,
				location));
		}

		final List<StoreSource> sources = new ArrayList<>(byShop.values());
		// Cheapest first (most useful for restocking); unknown prices sort last.
		sources.sort(Comparator.comparingInt(StoreSource::priceValue));
		return Collections.unmodifiableList(sources);
	}

	private static String cleanShop(String name)
	{
		String s = name.trim();
		while (s.endsWith(".") || s.endsWith(","))
		{
			s = s.substring(0, s.length() - 1).trim();
		}
		return s;
	}

	/** Strip wiki markup from a location string: [[A|B]] -> B, [[A]] -> A, drop stray brackets. */
	private static String cleanLocation(String raw)
	{
		if (raw == null || raw.isEmpty())
		{
			return "";
		}
		String s = raw.replaceAll("\\[\\[[^\\]|]*\\|([^\\]]*)\\]\\]", "$1");
		s = s.replaceAll("\\[\\[([^\\]]*)\\]\\]", "$1");
		s = s.replaceAll("[\\[\\]]", "");
		return s.trim();
	}

	private static String str(JsonObject o, String key)
	{
		final JsonElement e = o.get(key);
		if (e == null || e.isJsonNull())
		{
			return "";
		}
		try
		{
			return e.isJsonArray() ? arrayFirst(e.getAsJsonArray()) : e.getAsString();
		}
		catch (Exception ex)
		{
			return "";
		}
	}

	private static String arrayFirst(JsonArray arr)
	{
		return arr.size() == 0 ? "" : arr.get(0).getAsString();
	}
}

